def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform divider, then intersect corresponding nonzero cells
    # on either side of it.
    for r, row in enumerate(grid):
        if row[0] != 0 and all(v == row[0] for v in row):
            top, bottom = grid[:r], grid[r + 1:]
            return [
                [2 if a != 0 and b != 0 else 0 for a, b in zip(x, y)]
                for x, y in zip(top, bottom)
            ]

    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            left_width = c
            right_start = c + 1
            return [
                [2 if row[j] != 0 and row[right_start + j] != 0 else 0
                 for j in range(left_width)]
                for row in grid
            ]

    return []
